import React, { useEffect, useState } from "react";
import axios from "axios";
import "./Dashboard.css";


function Dashboard() {
  const [transactions, setTransactions] = useState([]);
  const [title, setTitle] = useState("");
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState("");
  const [date, setDate] = useState("");
  const [notes, setNotes] = useState("");
  const [page, setPage] = useState(1);

  const token = localStorage.getItem("token");

  const fetchTransactions = async () => {
    const res = await axios.get(
      `http://localhost:5000/transactions?page=${page}`,
      {
        headers: { authorization: token },
      }
    );
    setTransactions(res.data);
  };

  useEffect(() => {
    fetchTransactions();
  }, [page]);

  const addTransaction = async () => {
    await axios.post(
      "http://localhost:5000/transactions",
      { title, amount, category, date, notes },
      { headers: { authorization: token } }
    );
    setTitle("");
  setAmount("");
  setCategory("");
  setDate("");
  setNotes("");
    fetchTransactions();
  };

  const deleteTransaction = async (id) => {
    await axios.delete(`http://localhost:5000/transactions/${id}`, {
      headers: { authorization: token },
    });

    fetchTransactions();
  };

  const totalExpense = transactions.reduce(
    (acc, t) => acc + parseFloat(t.amount),
    0
  );

  const handleLogout = () => {
    localStorage.removeItem("token");
    window.location.href = "/";
  };

  return (
  <div className="dashboard-container">
    <div className="dashboard-header">
      <h2>Expense Dashboard</h2>
      <button className="logout-btn" onClick={handleLogout}>
        Logout
      </button>
    </div>

    <div className="summary-card">
      Total Expense: ₹ {totalExpense}
    </div>

    <div className="form-section">
  <h3>Add Transaction</h3>

  <input
    placeholder="Title"
    value={title}
    onChange={(e) => setTitle(e.target.value)}
  />

  <input
    placeholder="Amount"
    value={amount}
    onChange={(e) => setAmount(e.target.value)}
  />

  <input
    placeholder="Category"
    value={category}
    onChange={(e) => setCategory(e.target.value)}
  />

  <input
    type="date"
    value={date}
    onChange={(e) => setDate(e.target.value)}
  />

  <input
    placeholder="Notes"
    value={notes}
    onChange={(e) => setNotes(e.target.value)}
  />

  <button className="add-btn" onClick={addTransaction}>
    Add
  </button>
</div>


    <h3>Transactions</h3>

    {transactions.length === 0 && <p>No transactions found</p>}

    {transactions.map((t) => (
      <div key={t.id} className="transaction-card">
        <p><strong>{t.title}</strong> - ₹{t.amount}</p>
        <p>Category: {t.category}</p>
        <p>Date: {t.date}</p>
        <button
          className="delete-btn"
          onClick={() => deleteTransaction(t.id)}
        >
          Delete
        </button>
      </div>
    ))}

    <button className="load-btn" onClick={() => setPage(page + 1)}>
      Load More
    </button>
  </div>
);

}

export default Dashboard;
